/** 
 * Starts the service if not started already and sets the stop reason for one or all downloads. To clear stop reason, pass  {@link Download#STOP_REASON_NONE}.
 * @param context A {@link Context}.
 * @param clazz The concrete download service to be started.
 * @param id The content id, or {@code null} to set the stop reason for all downloads.
 * @param stopReason An application defined stop reason.
 * @param foreground Whether the service is started in the foreground.
 */
public static void sendSetStopReason(Context context,Class<? extends DownloadService> clazz,@Nullable String id,int stopReason,boolean foreground){
  Intent intent=buildSetStopReasonIntent(context,clazz,id,stopReason,foreground);
  startService(context,intent,foreground);
}
